// "Spiders Garden" GDY, bundled as a string so the demo does not depend on the copy baked into the
// @griddly/wasm virtual FS. Generated by tools/gen_spiders_garden.py; the source of truth is
// resources/games/Single-Player/Mini-Grid/minigrid-spiders-garden.yaml in the Griddly repo.
import { parse } from "yaml";

import gdy from "./minigrid-spiders-garden.yaml?raw";

export const SPIDERS_GDY: string = gdy;

/** Level names and blurbs, from the `# Name | blurb` comment above each level in the GDY. */
export const SPIDERS_LEVELS: { name: string; blurb: string }[] = [...gdy.matchAll(/^ {4}# (.+)\n {4}- \|/gm)].map((m) => {
  const [name, blurb = ""] = m[1]!.split("|").map((x) => x.trim());
  return { name: name!, blurb };
});

type Gdy = { Environment: { Observers?: Record<string, { Type?: string; TrackAvatar?: boolean; Width?: number; Height?: number }> } };

/**
 * Cameras = the render observers named in the GDY. The engine renders them; the demo only blits.
 * The global `Sprite2D` observer shows the whole level; avatar-tracking SPRITE_2D observers follow the gnome.
 */
export const CAMERAS: { name: string; label: string; follows: boolean }[] = Object.entries(
  (parse(gdy) as Gdy).Environment.Observers ?? {}
)
  .filter(([name, o]) => name === "Sprite2D" || o.Type === "SPRITE_2D")
  .map(([name, o]) => ({
    name,
    follows: !!o.TrackAvatar,
    label: o.TrackAvatar ? `Follow ${o.Width}×${o.Height}` : "Whole map",
  }));
